import threading


# LOCK, protecting a critical section
class Counter:
    def __init__(self):
        self.count = 0
        self.mtx = threading.Lock()

    def increment(self):
        with self.mtx:
            self.count += 1

    def get_count(self):
        return self.count


# SEMAPHORE, limiting a resource pool
class ConnectionPool:
    def __init__(self):
        self.permits = threading.Semaphore(10)

    def acquire(self):
        self.permits.acquire()

    def release(self):
        self.permits.release()


if __name__ == "__main__":
    counter = Counter()
    counter.increment()
    counter.increment()
    print(f"Count: {counter.get_count()}")

    pool = ConnectionPool()
    pool.acquire()
    print("Connection acquired")
    pool.release()

